css:
.pt-quote { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; color: #000; }
.pt-quote table { width: 100%; border-collapse: collapse; }
.pt-head td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; }
.pt-head .pt-k, .pt-head .pt-k2 { width: 13%; font-weight: bold; background: #f2f2f2; }
.pt-head .pt-v { width: 47%; } .pt-head .pt-v2 { width: 27%; }
.pt-attn { margin: 8px 0 2px; font-weight: bold; }
.pt-subj { margin: 2px 0 6px; }
.pt-title { text-align: center; font-weight: bold; font-size: 13px; letter-spacing: 1px; border: 1px solid #000; border-bottom: 0; padding: 4px; background: #f2f2f2; }
.pt-items th { border: 1px solid #000; padding: 4px; font-size: 10px; background: #f2f2f2; text-align: center; }
.pt-items td { border: 1px solid #000; padding: 4px; vertical-align: top; }
.pt-items tr { page-break-inside: avoid; }
.c-sn { width: 5%; text-align: center; } .c-qty { width: 6%; text-align: center; }
.c-desc { width: 50%; line-height: 1.35; } .c-desc b { font-size: 11px; }
.c-num { width: 13%; text-align: right; white-space: nowrap; }
.pt-totals { margin-top: -1px; page-break-inside: avoid; }
.pt-totals td { border: 1px solid #000; padding: 4px 6px; }
.pt-totals .t-l { text-align: right; font-weight: bold; width: 74%; }
.pt-totals .t-v { text-align: right; width: 26%; white-space: nowrap; }
.pt-totals .t-split { font-weight: normal; font-size: 9px; }
.pt-totals .t-grand td { font-size: 12px; background: #f2f2f2; }
.pt-totals .t-words { text-align: left; font-style: italic; }
.pt-section { margin-top: 12px; font-weight: bold; text-decoration: underline; }
.pt-special { margin-top: 4px; line-height: 1.5; }
.pt-terms { margin-top: 4px; line-height: 1.4; text-align: justify; }
.pt-terms p { margin: 0 0 4px; }
.pt-sign { margin-top: 18px; page-break-inside: avoid; }
.pt-sign .s-r { text-align: right; width: 50%; }
.pt-sign img.s-stamp { width: 80px !important; max-width: 80px !important; height: auto !important; margin-right: 10px; vertical-align: middle; display: inline-block; }
.pt-sign img.s-sign { width: 120px !important; max-width: 120px !important; height: auto !important; vertical-align: middle; display: inline-block; }
